# comp labels excluding wall=3
from collections import deque,defaultdict
lab=np.full((30,30),-1,int); comps=[]
for r in range(30):
 for c in range(30):
  if g[r,c]==3 or lab[r,c]>=0: continue
  k=len(comps); q=deque([(r,c)]); lab[r,c]=k; cells=[]
  while q:
   x,y=q.popleft(); cells.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    xx,yy=x+dx,y+dy
    if 0<=xx<30 and 0<=yy<30 and g[xx,yy]!=3 and lab[xx,yy]<0:
     lab[xx,yy]=k; q.append((xx,yy))
  comps.append(cells)
for i,cells in enumerate(comps):
 vals=defaultdict(list)
 for r,c in cells:
  if g[r,c] not in (3,4): vals[g[r,c]].append((r,c))
 if vals:
  print(i,len(cells),(min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)),dict(vals))

# compute boundary distance per component by BFS inward from all component cells adjacent to non-component/outside
out=g.copy(); info=[]
for i,cells in enumerate(comps):
 S=set(cells); dist={}
 q=deque()
 for r,c in cells:
  if any((r+dr,c+dc) not in S for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
   dist[(r,c)]=0; q.append((r,c))
 while q:
  p=q.popleft(); r,c=p
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   n=(r+dr,c+dc)
   if n in S and n not in dist:
    dist[n]=dist[p]+1; q.append(n)
 tokens=sorted([(dist[p],int(g[p]),p) for p in cells if g[p] not in (3,4)])
 if tokens:
  print('component',i,'maxdepth',max(dist.values()),'tokens',tokens)
  # sequence colors ordered by depth; assume no duplicate depth
  colors=[v for d,v,p in tokens]
  ds=[d for d,v,p in tokens]
  print(' depths set', sorted(set(ds)))
  for p in cells:
   d=dist[p]
   # use repeated cyclic sequence from first token level; tokens consecutive starting d=0 for these
   out[p]=colors[d%len(colors)]
print('output rows:')
for row in out: print(' '.join(map(str,row)))

def shell_transform(arr, wall, bg):
 H,W=arr.shape; lab=np.full((H,W),-1,int); cs=[]
 for r in range(H):
  for c in range(W):
   if arr[r,c]==wall or lab[r,c]>=0: continue
   q=deque([(r,c)]);lab[r,c]=len(cs); cells=[]
   while q:
    p=q.popleft();cells.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=p[0]+dr,p[1]+dc
     if 0<=x<H and 0<=y<W and arr[x,y]!=wall and lab[x,y]<0:
      lab[x,y]=len(cs);q.append((x,y))
   cs.append(cells)
 out=arr.copy(); infos=[]
 for i,cells in enumerate(cs):
  S=set(cells);dist={};q=deque()
  for r,c in cells:
   if any((r+dr,c+dc) not in S for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):dist[(r,c)]=0;q.append((r,c))
  while q:
   p=q.popleft()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    n=(p[0]+dr,p[1]+dc)
    if n in S and n not in dist:dist[n]=dist[p]+1;q.append(n)
  toks=sorted((dist[p],int(arr[p]),p) for p in cells if arr[p]!=bg)
  if toks:
   colors=[v for dep,v,p in toks]
   print(i,len(cells),toks, 'max',max(dist.values()))
   for p in cells:out[p]=colors[dist[p]%len(colors)]
  infos.append((cells,dist,toks))
 return out,infos
